:root{--navy:#142f41;--deep:#102638;--ink:#162d3b;--body:#40545f;--yellow:#f0d64a;--paper:#f7f8f6;--soft:#eef1ee;--line:#d4e1e8;--focus:#145779;--max:1220px;--section:clamp(62px,7vw,94px)}*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:400 16px/1.7 Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}h1,h2,h3,p{margin-top:0}h1,h2,h3{line-height:1.15;letter-spacing:-.035em}p{color:var(--body)}a{color:inherit}img{max-width:100%;display:block}button,input{font:inherit}button{cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--focus);outline-offset:3px}.wrap{width:min(var(--max),calc(100% - 80px));margin:auto}.skip{position:absolute;top:0;left:-100vw;z-index:100;padding:15px;background:#fff}.skip:focus{left:14px}
.header{background:var(--deep);color:#fff;position:sticky;top:0;z-index:50}.header-line{min-height:84px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;flex-direction:column;border-left:5px solid var(--yellow);padding-left:17px;color:#fff;text-decoration:none;line-height:1.1}.brand strong{font-weight:800;font-size:clamp(23px,2.5vw,33px);letter-spacing:-.04em}.brand small{font-size:11px;font-weight:700;letter-spacing:.23em;margin-top:9px}.header-tools{display:flex;align-items:center;gap:14px}.header-contact{background:var(--yellow);font-weight:800;text-decoration:none;color:var(--deep);font-size:14px;padding:10px 20px}.menu-toggle{display:none;background:transparent;border:1px solid #869ca9;color:#fff;min-width:46px;min-height:46px;font-size:24px}.navigation{border-top:1px solid #ffffff25}.navigation .wrap{display:flex;align-items:center;min-height:59px;gap:clamp(13px,2.2vw,34px)}.navigation a{color:#ecf4f5;text-decoration:none;font-size:13px;font-weight:700;white-space:nowrap;padding:14px 0}.navigation a:hover,.navigation a[aria-current=page]{color:var(--yellow)}.navigation ul.tps-primary-menu{display:flex;align-items:center;gap:clamp(13px,2.2vw,34px);list-style:none;margin:0;padding:0}.navigation ul.tps-primary-menu li{margin:0;padding:0}.navigation ul.tps-primary-menu a{display:inline-block}.navigation .current-menu-item>a,.navigation .current_page_item>a{color:var(--yellow)}.nav-spacer{flex:1}
.breadcrumbs{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:28px 0;font-size:13px;color:#597180}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.18em;text-transform:uppercase;color:#526775;margin:0 0 20px}.display{font-size:clamp(38px,5.7vw,68px);font-weight:800;max-width:19ch;margin:0 0 24px}.lead{font-size:clamp(17px,1.7vw,20px);max-width:62ch;line-height:1.82}.hero{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);gap:clamp(35px,7vw,95px);align-items:center;padding:clamp(22px,4vw,55px) 0 var(--section)}.hero-media{min-height:330px;max-height:440px;overflow:hidden;background:var(--soft);border:1px solid var(--line);display:grid;place-items:center}.hero-media img{max-height:440px;width:100%;height:100%;object-fit:contain;padding:20px}.hero-media.no-photo{background:linear-gradient(130deg,#e4eef1,#f5f8f8)}.hero-media.no-photo span{max-width:12ch;text-align:center;font-size:clamp(26px,4vw,50px);font-weight:800;color:#6d8897}.actions{display:flex;flex-wrap:wrap;gap:15px;margin-top:35px}.button-primary,.button-outline,.button-soft{display:inline-flex;align-items:center;justify-content:space-between;text-decoration:none;gap:22px;padding:14px 21px;min-height:52px;font-size:15px;line-height:1.4;font-weight:800;border-radius:0}.button-primary{background:var(--yellow);border:1px solid var(--yellow);color:var(--deep)}.button-outline{background:#fff;border:1px solid #a6b9c2;color:var(--navy)}.button-soft{background:#edf2f4;border:1px solid var(--line);color:var(--navy)}.button-primary:hover{background:#ffe785}.button-outline:hover,.button-soft:hover{border-color:var(--navy)}
.section{padding:var(--section) 0}.section h2{font-size:clamp(29px,3.6vw,44px);margin:0 0 18px}.section-intro{max-width:68ch;line-height:1.8;margin:0 0 34px}.grid-three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.grid-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.feature{border:1px solid var(--line);background:#fff;padding:30px}.feature h3{font-size:20px;margin:0 0 14px}.feature p{font-size:15px}.feature .number{font-size:12px;letter-spacing:.16em;color:#526775;font-weight:800;display:block;margin-bottom:23px}.feature a{display:inline-block;margin-top:8px;color:var(--navy);font-weight:800;text-underline-offset:5px}.product-panel{border:1px solid var(--line);background:#fff;display:flex;flex-direction:column;min-width:0}.product-panel-media{height:220px;overflow:hidden;background:#f2f5f5;display:grid;place-items:center}.product-panel-media img{width:100%;height:100%;min-height:0;object-fit:contain;padding:18px}.product-panel-content{padding:25px;display:flex;flex:1;flex-direction:column}.product-panel h3{font-size:19px;margin:0 0 10px}.product-panel p{font-size:14px}.product-panel a{color:var(--navy);font-weight:800;text-decoration:none;border-top:1px solid var(--line);margin-top:auto;padding-top:18px}.product-panel a:hover{text-decoration:underline}.rating{display:flex;align-items:center;gap:9px;color:#c79813;letter-spacing:2px;margin:0 0 14px}.rating small{font-size:11px;color:#667b88;letter-spacing:0}.tag{font-size:12px;letter-spacing:.08em;font-weight:800;color:#637b88;text-transform:uppercase}.details{background:#fff;border-top:1px solid var(--line)}.detail-row{display:grid;grid-template-columns:185px 1fr;gap:20px;padding:17px 23px;border-bottom:1px solid var(--line)}.detail-row dt{font-weight:800}.detail-row dd{margin:0;color:var(--body)}.clean-list{padding:0;list-style:none;display:grid;gap:12px}.clean-list li{position:relative;padding-left:24px;color:var(--body)}.clean-list li:before{content:'';position:absolute;left:0;top:12px;width:8px;height:8px;background:var(--yellow)}.text-section{max-width:820px}.text-section p{font-size:17px;line-height:1.85}.photo-and-text{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:55px}.photo-and-text img{width:100%;max-height:460px;object-fit:cover}.contact-item{border-top:1px solid var(--line);padding:25px 0}.contact-item strong{display:block;margin-bottom:8px}.contact-item a{font-weight:700;text-underline-offset:5px}.contact-block{display:grid;grid-template-columns:.85fr 1.15fr;gap:60px}.cta-panel{background:var(--navy);padding:clamp(30px,5vw,60px);display:grid;grid-template-columns:1fr auto;align-items:center;gap:30px;color:white;margin:30px 0 var(--section)}.cta-panel h2{color:white;font-size:clamp(25px,3vw,36px);margin:0 0 14px}.cta-panel p{color:#d4e1e7;margin:0}.faq details{border-top:1px solid var(--line)}.faq details:last-child{border-bottom:1px solid var(--line)}.faq summary{cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;gap:16px;padding:24px 4px;font-size:17px;font-weight:750}.faq summary::-webkit-details-marker{display:none}.faq summary:after{content:'+';font-size:22px;font-weight:400}.faq details[open] summary:after{content:'−'}.faq details p{padding:0 32px 22px 4px;max-width:76ch}.muted{font-size:14px;color:#637683}.source-note{border-left:3px solid var(--line);padding:5px 0 5px 18px;color:#647884;font-size:13px;margin-top:32px}

/* Focused status layouts: one action for 404 and successful enquiries. */
.tps-status-main{display:grid;place-items:center;min-height:clamp(430px,62vh,690px);padding-block:clamp(56px,9vw,116px)}
.tps-status-panel{width:min(100%,630px);text-align:center;margin-inline:auto}
.tps-status-icon{width:86px;height:86px;margin:0 auto 30px;border:2px solid #b5cbd5;background:#eef5f6;border-radius:50%;display:grid;place-items:center;color:var(--navy)}
.tps-status-code{font-size:clamp(76px,14vw,140px);font-weight:800;letter-spacing:-.075em;line-height:1;margin:0 0 24px;color:var(--navy)}
.tps-status-panel h1{font-size:clamp(32px,5vw,49px);max-width:24ch;margin:0 auto 21px;overflow-wrap:anywhere}
.tps-status-message{max-width:56ch;margin:0 auto;font-size:clamp(16px,1.6vw,18px);line-height:1.8;color:var(--body)}
.tps-status-button{margin-top:29px;min-width:210px;max-width:100%;justify-content:center}
.tps-status-warning{font-size:14px;color:var(--ink);padding:12px 17px;margin:23px auto 0;border:1px solid #a1b9c4;background:#fff;max-width:50ch}
/* Early, task-focused form access on contact and quote pages only. */
.tps-info-quick-action{display:flex;align-items:flex-start;flex-direction:column;gap:11px;margin-top:26px}
.tps-info-quick-action .button-primary{gap:24px}
.tps-info-quick-action p{font-size:13px;line-height:1.65;color:#526a79;margin:0;max-width:48ch}
@media(max-width:560px){.tps-status-main{min-height:410px;padding-block:54px}.tps-status-icon{width:75px;height:75px;margin-bottom:23px}.tps-status-button{width:100%}.tps-info-quick-action .button-primary{width:100%}}
.footer{background:var(--deep);color:#e1edf1;padding:72px 0 26px;margin-top:70px}.footer-grid{display:grid;grid-template-columns:1.25fr 1fr 1fr 1fr;gap:40px}.footer h2{font-size:14px;color:white;letter-spacing:.1em;text-transform:uppercase;margin:0 0 21px}.footer .brand{display:flex;flex-direction:column;align-items:flex-start;width:max-content;max-width:100%}
.footer a{display:block;text-decoration:none;color:#d6e1e5;padding:4px 0;font-size:14px}.footer a:hover{color:var(--yellow);text-decoration:underline}.footer p{font-size:14px;color:#c2d2dc}.footer-brand{font-size:28px;font-weight:800;color:#fff}.footer hr{border:0;border-top:1px solid #ffffff32;margin:42px 0 25px}.footer-bottom{display:flex;gap:20px;align-items:center;justify-content:space-between;font-size:12px;color:#c1d0d9}.footer-bottom a{font-size:12px}
@media(max-width:1100px){.navigation .wrap{gap:16px}.navigation a{font-size:12px}.footer-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:860px){.wrap{width:min(100% - 48px,750px)}html.tps-enhanced .menu-toggle{display:block}.header-line{min-height:76px}.header-contact{display:none}html.tps-enhanced .navigation{display:none}html.tps-enhanced .navigation.is-open{display:block}.navigation .wrap{flex-direction:column;align-items:stretch;gap:0;padding-bottom:18px;min-height:0}.navigation ul.tps-primary-menu{flex-direction:column;align-items:stretch;gap:0;width:100%}.navigation ul.tps-primary-menu a{display:block}.navigation a{font-size:15px;white-space:normal;padding:13px 0;border-bottom:1px solid #ffffff20}.nav-spacer{display:none}.hero{grid-template-columns:1fr;gap:38px}.grid-three{grid-template-columns:repeat(2,minmax(0,1fr))}.photo-and-text,.contact-block{grid-template-columns:1fr}.cta-panel{grid-template-columns:1fr}.cta-panel .button-primary{justify-self:start}}
@media(max-width:560px){.wrap{width:calc(100% - 36px)}.brand{border-left-width:4px;padding-left:11px}.brand strong{font-size:21px}.brand small{font-size:9px;letter-spacing:.18em}.menu-toggle{min-width:44px}.header-tools{gap:8px}.breadcrumbs{padding:19px 0}.display{font-size:clamp(34px,9.2vw,43px)}.lead{font-size:17px}.hero{padding:15px 0 58px;gap:28px}.hero-media{min-height:250px}.actions{gap:12px}.actions a{width:100%}.section{padding:65px 0}.section h2{font-size:clamp(28px,7.5vw,36px)}.grid-three,.grid-two{grid-template-columns:1fr}.detail-row{grid-template-columns:1fr;gap:6px}.feature{padding:25px}.footer-grid{grid-template-columns:1fr;gap:30px}.footer-bottom{display:block}.footer-bottom a{margin-top:14px}.cta-panel .button-primary{width:100%}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

/* Material specification links: legible, underlined and easy to tap */
.detail-row dd a{display:inline-flex;align-items:center;min-height:28px;text-underline-offset:3px}

/* Breadcrumb hit areas: preserve visual style but meet minimum touch target height */
.breadcrumbs a{display:inline-flex;align-items:center;min-height:28px;padding-block:2px}

/* 2026 site-wide refinement: restrained B2B information design */

.footer-grid.footer-grid-calm{grid-template-columns:minmax(0,1.4fr) repeat(2,minmax(0,1fr));gap:clamp(28px,5vw,70px)}
.footer-grid-calm .footer-location{font-size:13px;color:#b2c6d0;margin-top:16px}
.footer-grid-calm .footer-about p{max-width:33ch;line-height:1.7}
.footer-grid-calm .footer-links a{padding:7px 0}
.section+.section{border-top:1px solid var(--line)}
.use-section{border-top:1px solid var(--line)}
.use-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:32px}
.use-item{border-top:2px solid var(--line);padding:17px 4px 4px;min-width:0}
.use-item .number{display:block;color:#60798a;font-size:12px;font-weight:800;letter-spacing:.10em;margin-bottom:13px}
.use-item h3{font-size:clamp(17px,1.6vw,21px);line-height:1.42;margin:0;font-weight:750}
.company-story{max-width:850px;margin-inline:auto}
.company-story p{max-width:70ch}
.breadcrumbs{padding-bottom:18px}
.hero{padding-top:clamp(15px,3vw,40px)}
.hero .lead{max-width:60ch}
.product-panel-content{display:flex;flex-direction:column;align-items:flex-start}
.product-panel-content a{margin-top:auto}
@media(max-width:860px){.use-list{grid-template-columns:1fr 1fr}.footer-grid.footer-grid-calm{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.use-list{grid-template-columns:1fr;gap:4px;margin-top:24px}.use-item{padding:17px 4px 15px}.footer-grid.footer-grid-calm{grid-template-columns:1fr;gap:26px}}

/* Contrast refinement: 12px eyebrow labels on off-white stay above WCAG 2.2 AA 4.5:1 */
.eyebrow,.use-item .number{color:#526a79}

/* Compact material specifications without duplicated introduction text */
.details-single{max-width:820px;margin-top:28px}

/* Home hero: prevent inner-page media rules from affecting homepage visual. */
.home .hero-media{min-height:0;max-height:none;overflow:visible;border:0;background:transparent}

/* WooCommerce catalogue presentation: product and category templates; purchasing is disabled in PHP. */
.catalog-crumb{display:inline-flex;align-items:baseline;gap:10px;min-width:0;max-width:100%}
.catalog-crumb [aria-current="page"]{overflow-wrap:anywhere;min-width:0}
.catalog-detail-hero{padding-bottom:var(--section)}
.catalog-detail-hero > div{min-width:0}
.catalog-detail-hero .lead{overflow-wrap:anywhere}
.catalog-product-image.no-photo span{overflow-wrap:anywhere}
.catalog-product-image{min-width:0}
.catalog-product-image img{object-fit:contain}
.catalog-category-intro{padding:clamp(25px,5vw,60px) 0 var(--section)}
.catalog-category-intro .display{max-width:25ch;overflow-wrap:anywhere}
.catalog-detail-hero .display{overflow-wrap:anywhere}
.catalog-product .breadcrumbs [aria-current="page"],.breadcrumbs [aria-current="page"]{overflow-wrap:anywhere;min-width:0}
.catalog-category-description p{font-size:inherit;line-height:inherit;max-width:62ch;overflow-wrap:anywhere}
.catalog-description .entry-content{max-width:76ch;overflow-wrap:anywhere}
.catalog-description .entry-content :where(img,iframe,video,table){max-width:100%}
.catalog-description .entry-content :where(pre,table){overflow-x:auto}
.catalog-tags{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}
.catalog-tag{display:inline-flex;align-items:center;min-height:44px;padding:9px 15px;background:#fff;border:1px solid var(--line);color:var(--navy);font-weight:700;text-decoration:none;font-size:14px;overflow-wrap:anywhere}
.catalog-tag:hover{border-color:var(--navy);text-decoration:underline}
.catalog-products-grid,.catalog-category-grid{margin-top:30px}
.catalog-card .product-panel-content h3{overflow-wrap:anywhere}
.catalog-card .product-panel-content p{overflow-wrap:anywhere}
.catalog-no-image{padding:24px;text-align:center;color:#526a79;font-size:18px;font-weight:800;overflow-wrap:anywhere}
.catalog-category-card{display:flex;flex-direction:column;gap:0;min-width:0}
.catalog-category-card h3{overflow-wrap:anywhere}
.catalog-category-card a{margin-top:auto}
.catalog-empty{padding:24px;border:1px solid var(--line);background:#fff}
.navigation.pagination{display:block;margin-top:36px;border:0}
.navigation.pagination .nav-links{display:flex;flex-wrap:wrap;gap:8px}
.navigation.pagination .page-numbers{display:inline-flex;min-width:44px;min-height:44px;justify-content:center;align-items:center;padding:8px 14px;background:#fff;border:1px solid var(--line);font-weight:750;text-decoration:none;color:var(--navy)}
.navigation.pagination .page-numbers.current{background:var(--navy);color:#fff}
.navigation.pagination .screen-reader-text{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
@media(max-width:860px){.catalog-detail-hero{grid-template-columns:minmax(0,1fr)}.catalog-product-image{min-height:250px}}
@media(max-width:560px){.catalog-card .product-panel-media{height:220px}.catalog-category-intro{padding-top:26px}.catalog-tag{max-width:100%}}

/* Native Gutenberg media on editorial pages; does not affect product or category layouts. */
.tps-editor-extras :where(img,video),main.wrap.section :where(.wp-block-image img,.wp-block-video video){max-width:100%;height:auto}
.tps-editor-extras :where(iframe,.wp-block-embed,.wp-block-table),main.wrap.section :where(iframe,.wp-block-embed,.wp-block-table){max-width:100%}
.tps-editor-extras :where(pre,.wp-block-table),main.wrap.section :where(pre,.wp-block-table){overflow-x:auto}
.tps-editor-extras :where(p,li,a),main.wrap.section :where(p,li,a){overflow-wrap:anywhere}

/* Inner-page footer shares the same horizontal alignment as the page content. */
body:not(.home) .footer > .container{width:min(var(--max),calc(100% - 80px));margin-inline:auto}
@media(max-width:860px){body:not(.home) .footer > .container{width:min(750px,calc(100% - 48px))}}
@media(max-width:560px){body:not(.home) .footer > .container{width:calc(100% - 36px)}}

/* WooCommerce catalogue card and enquiry form components. */
.catalog-card .catalog-product-link{display:flex;flex-direction:column;flex:1;text-decoration:none;border:0;margin:0;padding:0;color:inherit}
.catalog-card .catalog-product-link:hover .catalog-card-cta{text-decoration:underline}
.catalog-card .catalog-card-cta{display:block;border-top:1px solid var(--line);margin-top:auto;padding-top:18px;font-weight:800;color:var(--navy)}
.catalog-card .catalog-product-link:hover .product-panel-content h3{text-decoration:underline}
.catalog-product-image>.catalog-no-image{width:100%;font-size:clamp(24px,3vw,38px);text-align:center;font-weight:800;color:#526a79;padding:32px}
.catalog-gallery img{width:100%;height:220px;object-fit:contain}
.catalog-attributes table{border-collapse:collapse;width:100%;max-width:820px;background:#fff}
.catalog-attributes th,.catalog-attributes td{padding:16px;text-align:left;vertical-align:top;border:1px solid var(--line);overflow-wrap:anywhere}
/* Inquiry forms: square industrial cards, yellow action, navy supporting panel. */
.catalog-enquiry-section{padding-top:42px;scroll-margin-top:165px}
.catalog-enquiry-heading{margin-bottom:28px;max-width:750px}
.catalog-enquiry-heading .eyebrow{margin-bottom:13px}
.catalog-enquiry-lead{font-size:16px;max-width:67ch;line-height:1.75;margin:0}
.catalog-enquiry-layout{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(275px,.9fr);gap:24px;align-items:start}
.catalog-enquiry-form{min-width:0;display:grid;gap:21px;background:#fff;border:1px solid var(--line);padding:clamp(23px,3vw,39px)}
.catalog-form-required{font-size:13px;color:#526775;margin:0}
.catalog-form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.catalog-form-field{min-width:0}
.catalog-enquiry-form label{display:block;font-size:14px;font-weight:750;color:var(--ink);margin-bottom:7px}
.catalog-enquiry-form :is(input:not([type=hidden]),textarea){width:100%;border:1px solid #6f8592;padding:12px 14px;min-height:48px;border-radius:0;background:#fff;color:var(--ink);font:inherit;max-width:100%}
.catalog-enquiry-form :is(input,textarea):focus-visible{outline:3px solid var(--focus);outline-offset:2px}
.catalog-enquiry-form textarea{resize:vertical}
.catalog-form-divider{height:1px;background:var(--line);margin:2px 0 1px}
.catalog-form-subheading{font-size:19px;line-height:1.3;margin:0}
.catalog-selected-product{background:#eef1ee;border-left:4px solid var(--yellow);padding:13px 16px;margin:0;font-size:13px;color:var(--body)}
.catalog-selected-product strong{display:block;font-size:16px;color:var(--ink);margin-top:3px;overflow-wrap:anywhere}
.catalog-form-submit{justify-self:start;min-width:240px}
.catalog-form-privacy{font-size:13px;line-height:1.65;max-width:68ch;margin:0}
.catalog-form-privacy a{text-decoration:underline;text-underline-offset:3px}
.catalog-form-error{color:#7a2222;background:#fff0ee;border-left:5px solid #8e2c25;padding:15px 18px;max-width:100%;margin:0 0 20px}
.catalog-form-trap{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.catalog-enquiry-aside{background:var(--navy);color:#fff;padding:clamp(24px,3vw,35px);min-width:0}
.catalog-enquiry-aside-label{font-size:11px;letter-spacing:.16em;text-transform:uppercase;font-weight:800;color:#f0d64a;margin:0 0 15px}
.catalog-enquiry-aside h3{font-size:clamp(22px,2.5vw,28px);line-height:1.28;margin:0 0 25px;overflow-wrap:anywhere}
.catalog-enquiry-steps{list-style:none;counter-reset:enquiry-step;display:grid;gap:24px;margin:0;padding:0}
.catalog-enquiry-steps li{position:relative;padding-left:40px;counter-increment:enquiry-step;min-width:0;font-size:13px;line-height:1.65;color:#e3eaf0}
.catalog-enquiry-steps li::before{content:counter(enquiry-step,decimal-leading-zero);position:absolute;left:0;top:0;color:var(--yellow);font-size:13px;font-weight:800}
.catalog-enquiry-steps strong{display:block;color:#fff;font-size:14px;line-height:1.5;margin-bottom:5px}
.catalog-enquiry-aside-footer{margin:30px 0 0;padding-top:20px;border-top:1px solid #ffffff33;color:#d9e5ed;font-size:12px;line-height:1.7}
@media(max-width:860px){.catalog-enquiry-layout{grid-template-columns:1fr}.catalog-enquiry-aside{padding:26px}.catalog-enquiry-steps{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.catalog-enquiry-steps li{padding-left:0;padding-top:26px}}
@media(max-width:560px){.catalog-form-fields,.catalog-enquiry-steps{grid-template-columns:1fr}.catalog-enquiry-form{gap:18px}.catalog-form-submit{justify-self:stretch;min-width:0}.catalog-enquiry-steps li{padding-left:39px;padding-top:0}.catalog-enquiry-aside{padding:25px}}

/* 1.9.0: bilingual header controls and source-backed information pages */
.tps-info-section>.tps-prose{max-width:79ch;line-height:1.78;margin:18px 0 0;color:var(--body)}
.tps-copy-list{display:grid;gap:12px;max-width:80ch;padding-left:24px;line-height:1.75}
.tps-info-section .grid-three,.tps-info-section .grid-two{margin-top:24px}
.tps-info-section .feature p{line-height:1.7}
.tps-info-section .faq{margin-top:26px}
.tps-info-hero .hero-media img{width:100%;height:100%;object-fit:cover}
/* Keep long headings inside narrow mobile layouts. */
.tps-info-hero>div{min-width:0}
.tps-info-hero .display{overflow-wrap:anywhere;hyphens:auto}
.tps-info-hero .hero-media{min-width:0}

.tps-image-caption{display:block;padding:7px 10px;font-size:12px;color:#40545f;line-height:1.4;background:#f3f5f4}

/* TPS PACK — Material Index design system / 2026
   Single source of truth for layout, type, states and breakpoints.
   No external resources, no artificial badges or unverified claims. */
:root {
  --navy:#142f41; --deep:#0f2534; --ink:#162d3b; --body:#40545f;
  --muted:#536570; --yellow:#f0d64a; --yellow-hover:#f9e571;
  --paper:#f7f8f6; --surface:#fff; --soft:#eef1ee; --line:#d5dddc;
  --focus:#145779; --container:1220px;
  --s1:8px;--s2:12px;--s3:16px;--s4:24px;--s5:32px;--s6:48px;--s7:72px;--s8:104px;
  --section:104px;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:var(--header-offset,144px)}
body{margin:0;background:var(--paper);color:var(--ink);font:400 16px/1.7 Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}
button,input,select{font:inherit}button{cursor:pointer;color:inherit}
a{color:inherit;text-decoration:none}a,button{-webkit-tap-highlight-color:transparent}
img{display:block;max-width:100%}p,h1,h2,h3{margin:0}p{line-height:1.73}
h1,h2,h3{letter-spacing:-.045em;line-height:1.14;text-wrap:balance;font-weight:750}
h1{font-size:clamp(46px,5.15vw,76px)}h2{font-size:clamp(31px,3.4vw,43px)}h3{font-size:20px}
.container,.technical-layout{width:min(var(--container),calc(100% - 88px));margin-inline:auto}
.icon{width:20px;height:20px;flex:none}
[hidden]{display:none!important}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip{position:fixed;z-index:90;top:-110px;left:16px;background:#fff;padding:12px 18px;border:2px solid var(--navy)}.skip:focus{top:12px}
:focus-visible{outline:3px solid var(--focus);outline-offset:3px}
.header :focus-visible,.hero :focus-visible,.footer :focus-visible{outline-color:var(--yellow)}
.eyebrow{font-size:12px;line-height:1.5;font-weight:800;text-transform:uppercase;letter-spacing:.13em;color:var(--muted)}
.button{display:inline-flex;align-items:center;justify-content:space-between;gap:26px;min-height:54px;border:1px solid transparent;padding:14px 24px;background:var(--yellow);color:var(--deep);font-weight:800;font-size:15px;line-height:1.35;border-radius:2px;transition:background .15s,border-color .15s}
.button:hover{background:var(--yellow-hover)}.button .icon{width:19px;height:19px}
.text-link,.hero-secondary{display:inline-flex;align-items:center;gap:12px;min-height:44px;font-size:15px;font-weight:750;line-height:1.5;text-decoration:none}
.text-link:hover,.hero-secondary:hover{text-decoration:underline;text-underline-offset:5px}
.text-link .icon,.hero-secondary .icon{width:18px;height:18px}
/* Navigation: one baseline and one independent mobile state */
.header{position:sticky;top:0;z-index:20;background:var(--deep);color:#fff;border-bottom:1px solid #ffffff20}
.header-main{display:grid;grid-template-columns:184px minmax(260px,1fr) auto;column-gap:clamp(23px,3vw,48px);align-items:center;min-height:96px}
.brand{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;white-space:nowrap;line-height:1}
.brand strong{font-size:27px;font-weight:800;letter-spacing:-.048em;line-height:1.03}
.brand small{font-size:10px;line-height:1.35;letter-spacing:.23em;font-weight:750;margin-top:8px}
.header .brand{padding-left:14px;border-left:3px solid var(--yellow)}
.search{height:54px;display:flex;align-items:center;gap:14px;min-width:0;background:#fff;color:var(--ink);border:1px solid #afc0c6;padding-left:18px;border-radius:2px}
.search:focus-within{outline:3px solid var(--yellow);outline-offset:3px}
.search>.icon{height:21px;width:21px}
.search input{border:0;min-width:0;flex:1;outline:0;padding:10px 0;background:transparent;font-size:16px;color:var(--ink)}
.search input::placeholder{color:#536673;opacity:1}
.search button{border:0;min-width:59px;align-self:stretch;display:grid;place-items:center;background:var(--yellow)}
.search button:hover{background:var(--yellow-hover)}
.header-actions{display:flex;align-items:center;gap:12px}
.menu-button{position:relative;display:grid;place-items:center;background:transparent;border:0;color:#fff;min-width:48px;min-height:48px;padding:9px}
.menu-button>.icon{width:24px;height:24px;filter:brightness(0) invert(1)}

.menu-button{display:none}
html:not(.tps-enhanced) .search-toggle{display:none}
.navigation{background:var(--deep);border-top:1px solid #ffffff20}
.navigation>.container{display:flex;align-items:center;justify-content:space-between;gap:13px;min-height:50px}
.navigation button,.navigation a{background:transparent;border:0;color:#e2eaed;font-size:13px;font-weight:720;white-space:nowrap;min-height:48px;padding:10px 0}
.navigation button[aria-pressed=true],.navigation button:hover,.navigation a:hover{color:var(--yellow)}
.navigation ul.tps-primary-menu{display:flex;align-items:center;flex-wrap:wrap;gap:13px;min-height:50px;padding:0;margin:0;list-style:none}.navigation ul.tps-primary-menu a{display:inline-flex;align-items:center}.navigation .current-menu-item>a,.navigation .current_page_item>a{color:var(--yellow)}
.header.is-compact .header-main{min-height:72px}.header.is-compact .search{height:49px}
/* Hero: factual industrial editorial, no generic ornaments */
.hero-shell{margin-top:34px}
.hero{display:grid;grid-template-columns:minmax(0,1.17fr) minmax(360px,.83fr);align-items:stretch;min-height:540px;background:var(--navy);color:white;overflow:hidden;border-radius:2px}
.hero-copy{min-width:0;display:flex;flex-direction:column;justify-content:center;align-items:flex-start;padding:clamp(52px,5.3vw,84px) clamp(40px,5vw,76px)}
.hero .eyebrow{color:var(--yellow);margin-bottom:29px;max-width:45ch;letter-spacing:.13em}
.hero h1{line-height:1.055;margin:0 0 26px;max-width:670px;font-weight:800;letter-spacing:-.052em}
.hero .headline-second{display:block;color:var(--yellow)}
.hero .intro{font-size:17px;line-height:1.75;max-width:50ch;color:#e1e9ec;margin-bottom:36px}
.hero-actions{display:flex;align-items:center;gap:14px 26px;flex-wrap:wrap}
.hero .button{min-height:56px}
.hero-secondary{color:white;font-size:15px}.hero-secondary .icon{filter:brightness(0) invert(1)}
.hero-visual{position:relative;min-width:0;min-height:540px;background:#ebf0ed;display:flex;align-items:center;justify-content:center;flex-direction:column;overflow:hidden;border-left:1px solid #ffffff1a}
.hero-visual::before{content:"";position:absolute;inset:34px;border:1px solid #b7c6c2;pointer-events:none}
.hero-visual::after{content:"TPS  /  01";position:absolute;top:53px;right:51px;color:var(--muted);font-size:12px;line-height:1.3;font-weight:800;letter-spacing:.12em}
.hero-visual>img:first-child{position:relative;z-index:1;width:min(79%,333px);height:auto;max-height:300px;object-fit:contain;mix-blend-mode:multiply;margin-top:-20px}
.material-caption{position:absolute;bottom:58px;left:54px;right:54px;padding-top:14px;border-top:1px solid #b9c6c5;color:var(--navy);font-size:13px;line-height:1.4;letter-spacing:.08em;font-weight:800;text-transform:uppercase}
/* Supplier trace is real business context, not a decorative feature grid */
.supplier-note{display:flex;align-items:center;justify-content:space-between;gap:16px 32px;padding:28px 0;border-bottom:1px solid var(--line);font-size:14px;line-height:1.6;color:var(--body)}
.supplier-note span:first-child{font-weight:800;color:var(--ink)}
/* Product groups as generous, consistent material index rows */
.categories{margin-top:var(--section);padding:0}
.section-heading{display:flex;justify-content:space-between;align-items:end;gap:26px;margin-bottom:22px}
.section-heading h2{font-weight:800}
.section-heading .text-link{flex:none;color:var(--navy);white-space:normal}
.section-intro{color:var(--body);font-size:16px;line-height:1.7;margin:0 0 33px;max-width:58ch}
.category-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 42px;border-top:1px solid var(--line)}
.category-tile{display:grid;grid-template-columns:30px 104px minmax(0,1fr) 22px;align-items:center;text-align:left;gap:20px;min-width:0;min-height:147px;background:transparent;border:0;border-bottom:1px solid var(--line);padding:20px 3px;border-radius:0;transition:background .15s}
.category-tile:hover{background:#edf1ee}
.category-tile[aria-pressed=true]{background:#eaf0ec;box-shadow:inset 3px 0 var(--navy)}
.category-index{font-size:12px;letter-spacing:.065em;color:var(--muted);font-weight:800;font-variant-numeric:tabular-nums}
.category-tile>img:not(.icon){width:104px;height:105px;object-fit:contain;background:white;padding:9px;mix-blend-mode:normal;border:1px solid #e0e7e4;position:static;transition:none}
.category-tile>span[data-category-name]{min-width:0;overflow-wrap:anywhere;font-size:19px;line-height:1.35;font-weight:750;letter-spacing:-.025em}
.category-tile>.icon{display:block;height:20px;width:20px;justify-self:end}
.category-tile::after{display:none}
/* Products: legibility and unit comparison before decoration */
.technical-layout{margin:var(--section) auto 0;display:block;padding:0}.technical-content{min-width:0}
.products{width:100%;padding:0;margin:0}
.product-grid{display:grid;grid-template-columns:1fr;gap:0;border-top:1px solid var(--line)}
.product-card{display:grid;grid-template-columns:166px minmax(0,1fr) 207px;gap:0 33px;align-items:center;min-width:0;padding:30px 4px;border:0;border-bottom:1px solid var(--line);background:transparent;border-radius:0;transition:background .15s ease}
.product-card:hover{background:#eff2ef}
.product-image{grid-column:1;grid-row:1/4;display:flex;align-items:center;justify-content:center;width:166px;height:155px;margin:0;background:white;border:1px solid #e1e7e4;border-radius:2px;overflow:hidden}
.product-image img{width:100%;height:100%;object-fit:contain;padding:15px;mix-blend-mode:normal}
.product-card h3{grid-column:2;grid-row:1;margin:0 0 12px;font-size:21px;line-height:1.35;letter-spacing:-.03em;font-weight:800}
.product-meta{grid-column:2;grid-row:2/4;font-size:16px;line-height:1.85;color:var(--body);margin:0;align-self:start}
.product-card .price{grid-column:3;grid-row:1;margin:0;font-size:26px;line-height:1.3;font-weight:800;letter-spacing:-.03em}
.product-card .vat{grid-column:3;grid-row:2;color:var(--muted);font-size:13px;line-height:1.5;margin:8px 0 17px}
.product-card .button{grid-column:3;grid-row:3;width:100%;min-height:52px;padding:13px 16px;background:transparent;border:1px solid #7f97a0;color:var(--navy);font-size:15px;font-weight:750;gap:9px;justify-content:space-between;border-radius:2px}
.product-card .button:hover{background:var(--navy);border-color:var(--navy);color:#fff}
.product-card .button .icon{height:18px;width:18px}.product-card .button:hover .icon{filter:brightness(0) invert(1)}
.result-note{margin-top:10px;color:var(--muted);font-size:15px}.result-note:empty{display:none}
.source-note{color:var(--muted);font-size:14px;line-height:1.8;max-width:74ch;margin:24px 0 0}
.source-note .source-link{display:inline-flex;align-items:center;min-height:44px;margin-left:5px;text-decoration:underline;text-underline-offset:4px;font-weight:750}
.empty{grid-column:1/-1;padding:42px 0;border-bottom:1px solid var(--line)}.empty p{margin-bottom:18px}.empty .text-link{margin-left:22px}
/* Advice: a clear support route with deliberately different composition */
.advice{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:56px;margin-top:var(--section);padding:61px 0 62px;border-top:2px solid var(--navy);border-bottom:1px solid var(--line);border-left:0;border-right:0;border-radius:0;background:transparent}
.advice .eyebrow{margin-bottom:18px;color:var(--navy)}
.advice h2{font-size:clamp(31px,3vw,43px);margin-bottom:19px;max-width:27ch}
.advice p:last-child{font-size:17px;color:var(--body);max-width:57ch;line-height:1.78}
.advice .button{min-width:200px;background:var(--navy);color:#fff}.advice .button:hover{background:#294f63}.advice .button .icon{filter:brightness(0) invert(1)}
/* Local business context */
.about{margin-top:var(--section);margin-bottom:var(--section);display:grid;grid-template-columns:minmax(0,1.04fr) minmax(0,.96fr);gap:clamp(44px,6vw,88px);align-items:center}
.company-photo{width:100%;height:360px;object-fit:cover;object-position:center;border-radius:2px}
.about-copy{max-width:540px}.about .eyebrow{margin-bottom:21px}
.about h2{font-size:clamp(31px,3vw,42px);margin-bottom:23px;max-width:20ch}
.about-copy>p:not(.eyebrow){font-size:17px;line-height:1.85;color:var(--body);margin-bottom:25px}.about .text-link{color:var(--navy)}
/* Footer */
.footer{background:var(--deep);color:#fff;padding:66px 0 28px}
.footer-grid{display:grid;grid-template-columns:1.05fr 1.2fr .75fr;gap:clamp(32px,4vw,74px)}
.footer .brand strong{font-size:26px}.footer .brand small{font-size:10px}
.footer-summary{margin-top:23px;font-size:14px;color:#d1dce1}
.footer h2{font-size:16px;font-weight:800;letter-spacing:0;margin-bottom:19px}
.footer address{font-style:normal;color:#d1dce1;font-size:15px;line-height:1.85;margin-bottom:13px}
.footer p{font-size:14px;color:#d1dce1}.footer-links a{display:flex;align-items:center;min-height:44px;font-size:14px;color:#d1dce1}.footer-links a:hover{color:var(--yellow)}
.footer-bottom{display:flex;justify-content:space-between;align-items:center;gap:22px;border-top:1px solid #ffffff30;margin-top:56px;padding-top:21px}
.footer-bottom p{font-size:13px}.footer-bottom a{display:inline-flex;align-items:center;min-height:44px;font-size:14px}
/* Accessible native dialogs with compact-height layout */
dialog{border:1px solid var(--line);border-radius:4px;width:min(800px,calc(100% - 32px));max-height:calc(100dvh - 32px);padding:30px;color:var(--ink);background:#fff;box-shadow:0 22px 56px #0f263c36;overflow:auto}
dialog::backdrop{background:#0c1b29bc}
.dialog-close{position:sticky;top:0;float:right;min-width:46px;min-height:46px;display:grid;place-items:center;border:1px solid var(--line);background:#fff;border-radius:2px;z-index:2}
.detail-grid{clear:both;display:grid;grid-template-columns:235px minmax(0,1fr);gap:30px;align-items:start;padding-top:14px}
.detail-image{height:240px;width:100%;object-fit:contain}
.detail-grid h2{font-size:28px;margin-bottom:14px}.detail-grid p{font-size:16px;color:var(--body)}
.detail-grid .detail-price{font-size:28px;font-weight:800;color:var(--ink);margin:16px 0 3px}
.detail-pack{margin:11px 0 0}.detail-grid small{font-size:14px;color:var(--muted)}
label{display:block;font-size:15px;font-weight:750;margin:17px 0 8px}
select,input[type=number]{min-height:47px;border:1px solid #8399a3;background:white;color:var(--ink);border-radius:2px;padding:10px;font-size:16px}
select{width:100%}#quantity{width:110px;display:block;margin-bottom:20px}
.demo-note{font-size:14px;background:var(--soft);padding:15px;border-radius:2px;margin-top:19px}






/* Responsive */
@media(max-width:1120px){
  .container,.technical-layout{width:calc(100% - 64px)}
  .header-main{column-gap:18px;grid-template-columns:160px minmax(160px,1fr) auto}
  .navigation>.container{gap:9px}.navigation button,.navigation a{font-size:12px}
  .hero{grid-template-columns:minmax(0,1.09fr) minmax(295px,.91fr);min-height:455px}
  .hero-copy{padding:44px}.hero h1{font-size:clamp(43px,5.1vw,60px)}
  .hero-visual{min-height:455px}
  .hero .intro{font-size:16px}
  .category-tile{grid-template-columns:24px 88px minmax(0,1fr) 18px;gap:13px;min-height:125px}
  .category-tile>img:not(.icon){width:88px;height:88px}.category-tile>span[data-category-name]{font-size:17px}
  .product-card{grid-template-columns:141px minmax(0,1fr) 175px;column-gap:23px}
  .product-image{width:141px;height:139px}.product-card .button{font-size:14px}
}
@media(max-width:900px){
  :root{--section:82px}
  .container,.technical-layout{width:calc(100% - 50px)}
  .header-main{grid-template-columns:minmax(0,1fr) auto;row-gap:14px;min-height:0;padding:18px 0}
  .search{grid-column:1/-1;grid-row:2;width:100%;height:54px}
  .search input{font-size:16px}html.tps-enhanced .menu-button{display:grid}
  html.tps-enhanced .navigation{display:none}html.tps-enhanced .navigation.is-open{display:block}
  .navigation>.container{flex-direction:column;align-items:stretch;max-height:calc(100dvh - 155px);overflow:auto;gap:0;padding:9px 0}
  .navigation ul.tps-primary-menu{flex-direction:column;align-items:stretch;flex-wrap:nowrap;gap:0;min-height:0;width:100%}.navigation ul.tps-primary-menu a{display:flex;min-height:48px}
  .navigation button,.navigation a{min-height:48px;text-align:left;white-space:normal;font-size:15px;padding:11px 12px}
  .header.is-compact .header-main{min-height:0;padding:12px 0}.header.is-compact .search{height:49px}
  .hero{grid-template-columns:minmax(0,1fr) minmax(270px,.95fr);min-height:420px}
  .hero-copy{padding:38px}.hero h1{font-size:clamp(40px,5.2vw,51px)}
  .hero-visual{min-height:420px}.hero-visual::before{inset:20px}.hero-visual::after{top:35px;right:37px}
  .hero-visual>img:first-child{width:min(82%,295px)}.material-caption{bottom:37px;left:39px;right:39px}
  .category-grid{column-gap:24px}
  .category-tile{grid-template-columns:22px 72px minmax(0,1fr) 18px;gap:12px;min-height:112px}
  .category-tile>img:not(.icon){width:72px;height:75px;padding:6px}.category-tile>span[data-category-name]{font-size:16px}
  .product-card{grid-template-columns:123px minmax(0,1fr) 165px;gap:0 18px}
  .product-image{width:123px;height:127px}.product-image img{padding:10px}
  .product-card h3{font-size:19px}.product-meta{font-size:15px}
  .advice{grid-template-columns:1fr;gap:28px}.advice .button{justify-self:start}
  .about{gap:38px}.company-photo{height:300px}
}
@media(max-width:650px){
  :root{--section:72px}
  .container,.technical-layout{width:calc(100% - 40px)}
  .header-main{padding:16px 0;row-gap:13px}
  .brand strong{font-size:23px}.brand small{font-size:9px;letter-spacing:.18em;margin-top:6px}
  .header-actions{gap:3px}
  .menu-button{min-width:44px;width:44px;padding:7px}
  .search{height:52px;gap:10px;padding-left:14px}.search button{min-width:53px}
  .hero-shell{margin-top:20px}
  .hero{display:flex;flex-direction:column;min-height:0}
  .hero-copy{padding:44px 29px 42px}
  .hero .eyebrow{font-size:11px;margin-bottom:23px}
  .hero h1{font-size:clamp(38px,9.1vw,56px);letter-spacing:-.052em;margin-bottom:22px}
  .hero .intro{font-size:16px;line-height:1.78;margin-bottom:29px}
  .hero-actions{gap:12px 20px}.hero .button{min-height:54px}
  .hero-secondary{font-size:15px}
  .hero-visual{height:225px;min-height:225px;border-left:0;border-top:1px solid #ffffff2b}
  .hero-visual::before{inset:16px}.hero-visual::after{top:28px;right:30px;font-size:11px}
