#products{width:100%!important;max-width:100%!important}


/* Fallback arrows work as native anchor links when the iOS file preview does not run scripts. */
html:not(.tps-sliders-ready) .slider-controls{display:none!important}
html.tps-sliders-ready .native-slider-controls{display:none!important}
.native-slider-controls{display:flex;justify-content:center;align-items:center;margin:0 auto;padding-top:20px}
.native-slider-controls .native-stage{display:none;align-items:center;justify-content:center;gap:14px}
.native-slider-controls .native-stage[data-native-stage="1"]{display:flex}
.native-arrow{box-sizing:border-box;display:inline-grid;place-items:center;width:48px;height:48px;border:1px solid #aebdc6;background:#fff;color:#173143;text-decoration:none;font-size:24px;line-height:1}
.native-arrow:not(.native-arrow-disabled):hover{background:#eaf1f4}
.native-arrow:focus-visible{outline:3px solid #b28b1a;outline-offset:3px}
.native-arrow-disabled{opacity:.3}
.product-card[id^="product-slide"]{scroll-margin-block-start:var(--header-offset,120px);scroll-margin-inline:0}

.native-slider-controls.native-variant-tablet,.native-slider-controls.native-variant-mid,.native-slider-controls.native-variant-desktop{display:none}
@media(min-width:651px) and (max-width:1100px){
 .native-product-controls.native-variant-mobile{display:none}
 .native-product-controls.native-variant-tablet{display:flex}
}
@media(min-width:1101px){
 .native-product-controls.native-variant-mobile{display:none}
 .native-product-controls.native-variant-desktop{display:flex}
}
body:has(#product-slide-2:target) .native-product-controls .native-stage{display:none}
body:has(#product-slide-2:target) .native-product-controls .native-stage[data-native-stage="2"]{display:flex}
body:has(#product-slide-3:target) .native-product-controls .native-stage{display:none}
body:has(#product-slide-3:target) .native-product-controls .native-stage[data-native-stage="3"]{display:flex}
body:has(#product-slide-4:target) .native-product-controls .native-stage{display:none}
body:has(#product-slide-4:target) .native-product-controls .native-stage[data-native-stage="4"]{display:flex}
body:has(#product-slide-5:target) .native-product-controls .native-stage{display:none}
body:has(#product-slide-5:target) .native-product-controls .native-stage[data-native-stage="5"]{display:flex}

@media(min-width:901px) and (max-width:1100px){.native-product-controls.native-variant-tablet{display:none}.native-product-controls.native-variant-mid{display:flex}}


/* TPS Pack informational experience — keep existing palette/photos/components */
:root { --material-line:#d4e1e8 }
.header-main{grid-template-columns:minmax(0,1fr) auto;gap:clamp(12px,2vw,28px)}
.header-contact{min-height:44px;padding:11px 18px;color:var(--deep);background:var(--yellow);border:1px solid var(--yellow);font-size:13px;font-weight:800;text-decoration:none;display:inline-flex;align-items:center;justify-content:center}
.header-contact:hover{background:var(--yellow-hover)}
.header-actions{gap:clamp(6px,1vw,18px)}
.header-main .brand{min-width:0}
.navigation a,.category-grid a.category-tile,.guide-link-grid a.guide-link{cursor:pointer;text-decoration:none}
.category-grid a.category-tile{color:var(--navy)}
.product-grid .product-card{grid-template-rows:auto auto auto auto 1fr auto;align-content:start}
.product-grid .product-card h3{margin-bottom:14px}
.product-grid .product-card .product-meta{min-height:0;margin-bottom:12px;line-height:1.6}
.material-widths{display:block;font-weight:700;color:var(--navy)}
.material-size{display:block;font-size:13px;color:var(--body);margin-top:3px}
.product-grid .material-purpose{margin:0 17px 18px;font-size:13px;color:var(--body);line-height:1.65;min-height:75px;max-width:40ch}
.product-grid .product-card>.button{margin-top:auto!important;min-height:48px}
.product-grid .product-card .button{font-size:14px}
.product-card .product-image{margin-bottom:18px}
.product-grid .product-card:focus-within{outline:2px solid #d6a633;outline-offset:2px}
.categories,.products,.selection-guide,.technical-faq{border-color:var(--material-line)}
.hero-review-cue{cursor:pointer}
.footer-links a[href="#categories"]{color:#e1edf2}
.product-card[hidden]{display:none!important}
#empty-materials[hidden]{display:none!important}
#empty-materials{padding:32px 16px;border:1px solid var(--material-line);background:#f2f6f7;color:var(--navy);line-height:1.7}
#empty-materials a{color:var(--navy);font-weight:800;text-decoration:underline}
/* Keep a single primary action and strong whitespace between content blocks */
.products .section-heading .text-link{padding:1rem;background:#edf2f4;border:1px solid var(--material-line)}
.products .section-heading [data-reset]{display:inline-flex!important}
@media (max-width:900px){.header-contact{display:none}.header-actions{gap:clamp(6px,1.5vw,14px)}}
@media (max-width:650px){
 .header-main{column-gap:clamp(4px,1.6vw,12px)}
 .header-actions{gap:clamp(2px,.75vw,10px)}
 .product-grid .material-purpose{min-height:0;margin:0 17px 24px;font-size:13px;line-height:1.6}
 .product-grid .product-card{grid-template-rows:auto auto auto auto 1fr auto}
 .product-grid .product-card .button{margin-top:auto!important}
}
@media (max-width:385px){.header-actions{gap:0}}
.product-card h3{min-height:0!important;margin-bottom:8px!important}


/* Homepage and inner pages follow the same information hierarchy and palette */
:root{--deep:#102638;--yellow:#f0d64a;--paper:#f7f8f6;--divider-soft:#d4e1e8}
.header .navigation .container{justify-content:flex-start;gap:clamp(16px,3vw,42px)}
.header .navigation a{white-space:nowrap}
.footer .footer-grid.footer-grid-calm{grid-template-columns:minmax(0,1.4fr) repeat(2,minmax(0,1fr));gap:clamp(25px,5vw,70px)}
.footer .footer-grid-calm .footer-short{color:#b8cad2;font-size:13px;margin-top:15px}
.footer .footer-grid-calm .footer-links a{padding:7px 0}
.footer .footer-grid-calm .brand{display:flex}
@media(max-width:860px){.footer .footer-grid.footer-grid-calm{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.footer .footer-grid.footer-grid-calm{grid-template-columns:1fr;gap:30px}}

/* Consistent muted small-label contrast across the page */
main :not(.hero) > .eyebrow,.selection-guide .eyebrow{color:#526a79}
main .hero .hero-copy > .eyebrow{color:var(--yellow)}

/* Fix desktop hero visual containment */
@media(min-width:901px){body.home .hero-visual,body.home .hero-media{overflow:hidden}}
